package in.onewish.web;
import in.onewish.config.Database;import in.onewish.dao.MenuDao;import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.IOException;import java.sql.*;import java.math.BigDecimal;
@WebServlet("/admin") public class AdminServlet extends HttpServlet {
 protected void doGet(HttpServletRequest q,HttpServletResponse s)throws ServletException,IOException{try(Connection c=Database.connect();Statement st=c.createStatement()){try(ResultSet r=st.executeQuery("SELECT COUNT(*),COALESCE(SUM(total),0) FROM orders")){r.next();q.setAttribute("stats",new Object[]{r.getInt(1),r.getBigDecimal(2)});}String status=q.getParameter("status");if(status==null||!java.util.Set.of("PLACED","PREPARING","READY","COMPLETED","CANCELLED").contains(status))status="";String date=q.getParameter("date");if(date==null||!date.matches("\\d{4}-\\d{2}-\\d{2}"))date="";q.setAttribute("filterStatus",status);q.setAttribute("filterDate",date);try(PreparedStatement p=c.prepareStatement("SELECT id,reference,customer_name,status,total,created_at FROM orders WHERE (?='' OR status=?) AND (?='' OR DATE(created_at)=?) ORDER BY created_at DESC LIMIT 200")){p.setString(1,status);p.setString(2,status);p.setString(3,date);p.setString(4,date);try(ResultSet r=p.executeQuery()){java.util.List<Object[]> rows=new java.util.ArrayList<>();while(r.next())rows.add(new Object[]{r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getBigDecimal(5),r.getTimestamp(6)});q.setAttribute("orders",rows);}}var d=new MenuDao();q.setAttribute("items",d.all());q.setAttribute("adminCategories",d.adminCategories());}catch(Exception e){getServletContext().log("Admin dashboard unavailable",e);}q.setAttribute("csrf",Web.csrf(q));q.getRequestDispatcher("/WEB-INF/views/admin.jsp").forward(q,s);}
 protected void doPost(HttpServletRequest q,HttpServletResponse s)throws IOException{if(!Web.validCsrf(q)){s.sendError(403);return;}try{String action=q.getParameter("action");if("status".equals(action)){String status=q.getParameter("status");if(!java.util.Set.of("PLACED","PREPARING","READY","COMPLETED","CANCELLED").contains(status))throw new IllegalArgumentException();try(Connection c=Database.connect();PreparedStatement p=c.prepareStatement("UPDATE orders SET status=? WHERE id=?")){p.setString(1,status);p.setLong(2,Long.parseLong(q.getParameter("id")));p.executeUpdate();}}else if("item".equals(action)){String n=q.getParameter("name"),desc=q.getParameter("description"),image=q.getParameter("image");if(n==null||n.isBlank()||n.length()>120||desc==null||desc.length()>1000||image==null||!image.startsWith("https://")||image.length()>500)throw new IllegalArgumentException();new MenuDao().save(Long.parseLong(q.getParameter("id")),n.trim(),desc,new BigDecimal(q.getParameter("price")),Long.parseLong(q.getParameter("category")),image,q.getParameter("type"),"on".equals(q.getParameter("available")));}Web.flash(q,"Changes saved.");}catch(Exception e){getServletContext().log("Admin update failed",e);Web.flash(q,"Could not save changes. Check the fields and database.");}s.sendRedirect(q.getContextPath()+"/admin");}
}
